import java.sql.Timestamp;

// Represents a single row from the reservations table
public class Reservation {
    private int id;
    private String studentName;
    private String spaceName;
    private Timestamp createdAt;

    // Used when loading existing rows from the database
    public Reservation(int id, String studentName, String spaceName, Timestamp createdAt) {
        this.id = id;
        this.studentName = studentName;
        this.spaceName = spaceName;
        this.createdAt = createdAt;
    }

    // Used before inserting a new booking (id and timestamp are generated by the DB)
    public Reservation(String studentName, String spaceName) {
        this.studentName = studentName;
        this.spaceName = spaceName;
    }

    public int getId() {
        return id;
    }

    public void setId(int id) {
        this.id = id;
    }

    public String getStudentName() {
        return studentName;
    }

    public void setStudentName(String studentName) {
        this.studentName = studentName;
    }

    public String getSpaceName() {
        return spaceName;
    }

    public void setSpaceName(String spaceName) {
        this.spaceName = spaceName;
    }

    public Timestamp getCreatedAt() {
        return createdAt;
    }

    public void setCreatedAt(Timestamp createdAt) {
        this.createdAt = createdAt;
    }
}